PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY NOT NULL, email TEXT NOT NULL UNIQUE, name TEXT, passwordHash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'VIEWER', createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, failedLoginCount INTEGER NOT NULL DEFAULT 0, lockedUntil DATETIME, passwordChangedAt DATETIME, mustChangePassword INTEGER NOT NULL DEFAULT 0, totpSecret TEXT, totpEnabled INTEGER NOT NULL DEFAULT 0, totpBackupCodes TEXT);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY NOT NULL, sessionToken TEXT NOT NULL UNIQUE, userId TEXT NOT NULL, expires DATETIME NOT NULL, FOREIGN KEY (userId) REFERENCES users(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS change_logs (
    id             TEXT PRIMARY KEY,
    tablaNombre    TEXT NOT NULL,
    entidadId      TEXT NOT NULL,
    usuarioId      TEXT NOT NULL,
    campo          TEXT NOT NULL,
    valorAnterior  TEXT,
    valorNuevo     TEXT,
    tipo           TEXT NOT NULL,
    fechaCambio    DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (usuarioId) REFERENCES users(id) ON DELETE CASCADE
  );
CREATE TABLE IF NOT EXISTS pisos_flotantes (
    id                  TEXT PRIMARY KEY,
    sku                 TEXT UNIQUE NOT NULL,
    categoriaPrincipal  TEXT,
    categoriaSecundaria TEXT,
    categoriaTerciaria  TEXT,
    tipoProducto        TEXT,
    origen              TEXT,
    nombre              TEXT NOT NULL,
    codigo              TEXT,
    marca               TEXT NOT NULL,
    linea               TEXT,
    tipoDeUso           TEXT,
    espesor             TEXT,
    espesorUm           TEXT,
    abrasion            TEXT,
    mantoIncorporado    TEXT,
    bisel               TEXT,
    ancho               TEXT,
    anchoUm             TEXT,
    largo               TEXT,
    largoUm             TEXT,
    base                TEXT,
    baseUm              TEXT,
    tablasPorCaja       INTEGER,
    precioM2            REAL,
    moneda              TEXT,
    precioCaja          REAL,
    pesoCaja            REAL,
    cajasPallet         INTEGER,
    pesoPallet          REAL,
    stock               INTEGER,
    imagenes            TEXT,
    precioEnvioCaja     REAL,
    garantia            TEXT,
    fichaTecnica        TEXT,
    archivoInstalacion  TEXT,
    descripcion         TEXT,
    isActive            INTEGER NOT NULL DEFAULT 1,
    createdAt           DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt           DATETIME DEFAULT CURRENT_TIMESTAMP
  , metadatos TEXT, sortOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS porcellanatos (
    id                  TEXT PRIMARY KEY,
    sku                 TEXT UNIQUE NOT NULL,
    categoriaPrincipal  TEXT,
    categoriaSecundaria TEXT,
    tipoProducto        TEXT,
    acabado             TEXT,
    terminacion         TEXT,
    origen              TEXT,
    nombre              TEXT NOT NULL,
    codigo              TEXT,
    marca               TEXT NOT NULL,
    linea               TEXT,
    tipoDeUso           TEXT,
    espesor             TEXT,
    espesorUm           TEXT,
    ancho               TEXT,
    anchoUm             TEXT,
    largo               TEXT,
    largoUm             TEXT,
    base                TEXT,
    baseUm              TEXT,
    precioM2            REAL,
    moneda              TEXT,
    precioCaja          REAL,
    stock               INTEGER,
    imagenes            TEXT,
    precioEnvioCaja     REAL,
    garantia            TEXT,
    fichaTecnica        TEXT,
    archivoInstalacion  TEXT,
    descripcion         TEXT,
    isActive            INTEGER NOT NULL DEFAULT 1,
    createdAt           DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt           DATETIME DEFAULT CURRENT_TIMESTAMP
  , metadatos TEXT, sortOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS revestimientos (
    id                  TEXT PRIMARY KEY,
    sku                 TEXT UNIQUE NOT NULL,
    categoriaPrincipal  TEXT,
    tipoProducto        TEXT,
    uso                 TEXT,
    material            TEXT,
    marca               TEXT,
    linea               TEXT,
    nombre              TEXT NOT NULL,
    espesor             TEXT,
    espesorUm           TEXT,
    ancho               TEXT,
    anchoUm             TEXT,
    largo               TEXT,
    largoUm             TEXT,
    baseTabla           TEXT,
    baseTablUm          TEXT,
    precioTabla         REAL,
    precioM2            REAL,
    precioMl            REAL,
    moneda              TEXT,
    imagenes              TEXT,
    flete               REAL,
    stock               INTEGER,
    fichaTecnica        TEXT,
    archivoInstalacion  TEXT,
    descripcion         TEXT,
    isActive            INTEGER NOT NULL DEFAULT 1,
    createdAt           DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt           DATETIME DEFAULT CURRENT_TIMESTAMP
  , metadatos TEXT, sortOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pisos_vinilicos (
    id                    TEXT PRIMARY KEY,
    sku                   TEXT UNIQUE NOT NULL,
    categoriaPrincipal    TEXT,
    categoriaSecundaria   TEXT,
    categoriaTerciaria    TEXT,
    tipoProducto          TEXT,
    material              TEXT,
    origen                TEXT,
    nombre                TEXT NOT NULL,
    codigo                TEXT,
    marca                 TEXT NOT NULL,
    linea                 TEXT,
    tipoDeUso             TEXT,
    espesorTotal          TEXT,
    espesorTotalUm        TEXT,
    espesorComposicion    TEXT,
    espesorComposicionUm  TEXT,
    capaDeUso             TEXT,
    mantoIncorporado      TEXT,
    tablasPorCaja         INTEGER,
    ancho                 TEXT,
    anchoUm               TEXT,
    largo                 TEXT,
    largoUm               TEXT,
    base                  TEXT,
    baseUm                TEXT,
    bisel                 TEXT,
    precioM2              REAL,
    moneda                TEXT,
    precioCaja            REAL,
    cajasPallet           INTEGER,
    pesoCaja              REAL,
    pesoPallet            REAL,
    stock                 INTEGER,
    imagenes              TEXT,
    precioEnvioCaja       REAL,
    garantia              TEXT,
    fichaTecnica          TEXT,
    archivoInstalacion    TEXT,
    descripcion           TEXT,
    isActive              INTEGER NOT NULL DEFAULT 1,
    createdAt             DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt             DATETIME DEFAULT CURRENT_TIMESTAMP
  , metadatos TEXT, sortOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS pisos_madera (
    id                  TEXT PRIMARY KEY,
    sku                 TEXT UNIQUE NOT NULL,
    categoriaPrincipal  TEXT,
    categoriaSecundaria TEXT,
    categoriaTerciaria  TEXT,
    subtipo             TEXT,
    subtipo2            TEXT,
    especie             TEXT,
    acabado             TEXT,
    terminacion         TEXT,
    origen              TEXT,
    marca               TEXT,
    linea               TEXT,
    nombre              TEXT,
    espesor             TEXT,
    espesorUm           TEXT,
    espesorLamina       TEXT,
    espesorLaminaUm     TEXT,
    ancho               TEXT,
    anchoUm             TEXT,
    largo               TEXT,
    largoUm             TEXT,
    base                TEXT,
    baseUm              TEXT,
    bisel               TEXT,
    precioM2            REAL,
    moneda              TEXT,
    precioCaja          REAL,
    stock               INTEGER,
    imagenes            TEXT,
    precioEnvioCaja     REAL,
    garantia            TEXT,
    fichaTecnica        TEXT,
    archivoInstalacion  TEXT,
    descripcion         TEXT,
    isActive            INTEGER NOT NULL DEFAULT 1,
    createdAt           DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt           DATETIME DEFAULT CURRENT_TIMESTAMP
  , metadatos TEXT, calidad TEXT, sortOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS decks (
    id                  TEXT PRIMARY KEY,
    sku                 TEXT UNIQUE NOT NULL,
    categoriaPrincipal  TEXT,
    tipoProducto        TEXT,
    material            TEXT,
    marca               TEXT,
    linea               TEXT,
    nombre              TEXT NOT NULL,
    espesor             TEXT,
    espesorUm           TEXT,
    ancho               TEXT,
    anchoUm             TEXT,
    largo               TEXT,
    largoUm             TEXT,
    baseTabla           TEXT,
    baseTablUm          TEXT,
    precioTabla         REAL,
    precioM2            REAL,
    precioMLineal       REAL,
    moneda              TEXT,
    imagenes              TEXT,
    flete               REAL,
    stock               INTEGER,
    fichaTecnica        TEXT,
    archivoInstalacion  TEXT,
    descripcion         TEXT,
    isActive            INTEGER NOT NULL DEFAULT 1,
    createdAt           DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt           DATETIME DEFAULT CURRENT_TIMESTAMP
  , metadatos TEXT, sortOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS maderas (
    id                    TEXT PRIMARY KEY,
    sku                   TEXT UNIQUE NOT NULL,
    tipoProducto          TEXT,
    nombre                TEXT NOT NULL,
    origen                TEXT,
    espesoresDisponibles  TEXT,
    medidas               TEXT,
    secado                TEXT,
    precio                REAL,
    unidadMedida          TEXT,
    moneda                TEXT,
    stock                 INTEGER,
    imagenes                TEXT,
    descripcion           TEXT,
    fichaTecnica          TEXT,
    archivoInstalacion    TEXT,
    isActive              INTEGER NOT NULL DEFAULT 1,
    createdAt             DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt             DATETIME DEFAULT CURRENT_TIMESTAMP
  , metadatos TEXT, sortOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS accesorios (
    id            TEXT PRIMARY KEY,
    sku           TEXT UNIQUE NOT NULL,
    tipoProducto  TEXT,
    subtipo       TEXT,
    nombre        TEXT NOT NULL,
    espesor       TEXT,
    dimensiones   TEXT,
    colores       TEXT,
    stock         INTEGER,
    imagenes        TEXT,
    descripcion   TEXT,
    isActive      INTEGER NOT NULL DEFAULT 1,
    createdAt     DATETIME DEFAULT CURRENT_TIMESTAMP,
    updatedAt     DATETIME DEFAULT CURRENT_TIMESTAMP
  , metadatos TEXT, sortOrder INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "auth_events" (
      id         TEXT NOT NULL PRIMARY KEY,
      type       TEXT NOT NULL DEFAULT 'LOGIN_OK',
      tipo       TEXT,
      userId     TEXT,
      email      TEXT,
      ip         TEXT,
      userAgent  TEXT,
      metadata   TEXT,
      createdAt  DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
      user_id    TEXT,
      user_agent TEXT,
      created_at DATETIME
    );
CREATE TABLE IF NOT EXISTS hero_media (
      id TEXT PRIMARY KEY,
      type TEXT NOT NULL,
      url TEXT NOT NULL,
      alt TEXT,
      sortOrder INTEGER NOT NULL DEFAULT 0,
      isActive INTEGER NOT NULL DEFAULT 1,
      createdAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
    );
CREATE INDEX idx_changelog_tabla ON change_logs (tablaNombre, entidadId);
CREATE INDEX idx_changelog_user  ON change_logs (usuarioId);
CREATE INDEX idx_changelog_fecha ON change_logs (fechaCambio);
CREATE INDEX idx_pf_sku      ON pisos_flotantes (sku);
CREATE INDEX idx_pf_marca    ON pisos_flotantes (marca);
CREATE INDEX idx_pf_active   ON pisos_flotantes (isActive);
CREATE INDEX idx_pc_sku    ON porcellanatos (sku);
CREATE INDEX idx_pc_marca  ON porcellanatos (marca);
CREATE INDEX idx_pc_active ON porcellanatos (isActive);
CREATE INDEX idx_rv_sku      ON revestimientos (sku);
CREATE INDEX idx_rv_marca    ON revestimientos (marca);
CREATE INDEX idx_rv_cat      ON revestimientos (categoriaPrincipal);
CREATE INDEX idx_rv_active   ON revestimientos (isActive);
CREATE INDEX idx_pv_sku    ON pisos_vinilicos (sku);
CREATE INDEX idx_pv_marca  ON pisos_vinilicos (marca);
CREATE INDEX idx_pv_active ON pisos_vinilicos (isActive);
CREATE INDEX idx_pm_sku    ON pisos_madera (sku);
CREATE INDEX idx_pm_marca  ON pisos_madera (marca);
CREATE INDEX idx_pm_active ON pisos_madera (isActive);
CREATE INDEX idx_dk_sku    ON decks (sku);
CREATE INDEX idx_dk_marca  ON decks (marca);
CREATE INDEX idx_dk_active ON decks (isActive);
CREATE INDEX idx_md_sku    ON maderas (sku);
CREATE INDEX idx_md_active ON maderas (isActive);
CREATE INDEX idx_ac_sku    ON accesorios (sku);
CREATE INDEX idx_ac_active ON accesorios (isActive);
CREATE INDEX idx_hero_media_active_order ON hero_media (isActive, sortOrder)
  ;
COMMIT;
