INSERT INTO porcellanatos VALUES('cmrjcsrxc00l9cjew8x1kg3dk','23092','Espacios Interiores','Accesorios','Pastinas','-','-','Nacional','Pastina Color Cedro','-','Weber','-','-','-',NULL,'-',NULL,'-',NULL,'2 | 5',NULL,NULL,'$',NULL,NULL,'19453-1.jpg',NULL,NULL,NULL,NULL,'La Pastina Weber Prestige en color Cedro es un mortero cementicio de alta performance diseñado para el tomado de juntas de 2 a 15 mm en porcelanatos y piezas de baja absorción. Su fórmula impermeable, antihongos y antialgas ofrece gran flexibilidad y resistencia, siendo ideal para superficies exigentes como piscinas, suelos con calefacción radiante y áreas de alto tránsito tanto en interiores como en exteriores. Se presenta en bolsas de 2 o 5 kg con una excelente adherencia y doble consistencia para uso en pisos y paredes.',1,'2026-07-13T15:04:48.481+00:00','2026-07-28T20:01:04.186+00:00',NULL,0);
INSERT INTO porcellanatos VALUES('cmrjcss7s00lccjewiff0aj6k','23093','Espacios Interiores','Accesorios','Pastinas','-','-','Nacional','Pastina Color Negro','-','Weber','-','-','-',NULL,'-',NULL,'-',NULL,'2 | 5',NULL,NULL,'$',NULL,NULL,'19453-1.jpg',NULL,NULL,NULL,NULL,'La Pastina Weber Prestige en color Negro es un mortero cementicio de alta performance diseñado para el tomado de juntas de 2 a 15 mm en porcelanatos y piezas de baja absorción. Su fórmula impermeable, antihongos y antialgas ofrece gran flexibilidad y resistencia, siendo ideal para superficies exigentes como piscinas, suelos con calefacción radiante y áreas de alto tránsito tanto en interiores como en exteriores. Se presenta en bolsas de 2 o 5 kg con una excelente adherencia y doble consistencia para uso en pisos y paredes.',1,'2026-07-13T15:04:48.856+00:00','2026-07-28T20:01:04.715+00:00',NULL,0);
INSERT INTO porcellanatos VALUES('cmrp8makh0000cj2oql5h4bxw','19436','Espacios Interiores','Accesorios','Limpiador','-','-','Nacional','Limpiador Weber 98-1005','-','Weber','-','-','-',NULL,'-',NULL,'-',NULL,'5',NULL,19740,'$',5,NULL,'19740',NULL,'-',NULL,NULL,'El Limpiador Weber es una solución de base ácida diseñada para la limpieza profunda de restos de obra como mezcla adhesiva, pastina, cal y yeso, además de eliminar manchas de sarro, moho, hongos y eflorescencias. Es apto para su uso en interiores y exteriores sobre porcelanatos, cerámicos y juntas, ofreciendo una efectiva acción desincrustante que remueve suciedad difícil sin dañar las piezas. Se presenta en bidones de 5 litros, rinde entre 6 y 12 m2 por litro según la dilución, y requiere el uso de elementos de protección personal para su aplicación.',1,'2026-07-17T17:54:24.641+00:00','2026-07-28T20:01:05.289+00:00',NULL,0);
INSERT INTO revestimientos VALUES('cmrjcssmv00lfcjewpnodsp5o','25383','Revestimiento Exterior','Revestimiento','Exterior','WPC','Max Core','Alistonado 5 varillas','Smoke Grey','25',NULL,'218.5',NULL,'2900',NULL,'0.64',NULL,28288,44.2,9.75,'usd','["/25383-1.jpg","/25383-2.jpg","/25383-3.jpg"]',NULL,NULL,NULL,NULL,'Este revestimiento exterior de la marca Max Core, línea Alistonado 5 varillas en color Smoke Grey, está fabricado en WPC (madera compuesta de polímero y fibra). Es un material duradero, resistente a la humedad, la decoloración y los insectos, diseñado para fachadas modernas que buscan la estética de la madera sin necesidad de mantenimiento periódico. Cada tabla tiene un espesor de 25 mm, un ancho de 218.5 mm y un largo de 2900 mm, cubriendo una superficie de 0.64 m2.',1,'2026-07-13T15:04:49.399+00:00','2026-08-05T21:08:27.358+00:00',NULL,0);
