INSERT INTO pisos_madera VALUES('cmrjcv9kp017xcjewtl6cfi8p','22323','Espacios Interiores','Pisos','Piso Ingenieria','Prefinished','Entablonado','Tauari Tostado','Semi Mate','MO','Paraguay','Max Core',NULL,NULL,'12.4',NULL,'3',NULL,'131',NULL,'Largo Variado',NULL,'2.82',NULL,'No',50,'U$S',141,NULL,'["/22323-1.jpg","/22323-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de ingeniería de Tauari Tostado presenta una elegante tonalidad beige dorada con vetas suaves, ideal para iluminar ambientes interiores con un toque rústico y sofisticado. Fabricado por Max Core en Paraguay, cuenta con un espesor de 12.4 mm, una lámina de madera noble de 3 mm y un acabado semi mate que resalta su brillo natural. Es una opción resistente, estable y de fácil mantenimiento, con un formato de entablonado de largos variados que aporta naturalidad y calidez al espacio.',1,'2026-07-13T15:06:44.665+00:00','2026-07-28T20:03:49.924+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcv9v70180cjewgg8vf9yh','24820','Espacios Interiores','Pisos','Piso Ingenieria','Prefinished','Entablonado','Tauari','Semi Mate','MO','Paraguay','Max Core',NULL,NULL,'12.4',NULL,'3',NULL,'131',NULL,'Largo Variado',NULL,'2.82',NULL,'No',55,'U$S',155.1,NULL,'["/24820-1.jpg","/24820-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de ingeniería de Tauari destaca por su tonalidad clara y vetas delicadas, brindando luminosidad y elegancia a cualquier ambiente interior. Fabricado por Max Core en Paraguay, posee un espesor de 12.4 mm con una capa noble de 3 mm y un acabado semi mate que realza la belleza natural de la madera. Su formato de entablonado con largos variados asegura una instalación con apariencia natural, ofreciendo una superficie estable, duradera y de gran calidez estética.',1,'2026-07-13T15:06:45.043+00:00','2026-07-28T20:03:50.556+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcva6n0183cjewpbpu0648','23116','Espacios Interiores','Pisos','Piso Ingenieria','Prefinished','Entablonado','Incienso Colorado','Semi Mate','MO','Paraguay','Max Core',NULL,NULL,'12.4',NULL,'3',NULL,'131',NULL,'Largo Variado',NULL,'2.82',NULL,'No',59,'U$S',166.38,NULL,'["/23116-1.jpg","/23116-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de ingeniería de Incienso Colorado ofrece una fragancia natural única y una tonalidad castaña con vetas bien marcadas que brindan calidez y confort al hogar. Fabricado por Max Core en Paraguay, presenta un espesor de 12.4 mm con una lámina de madera noble de 3 mm y un acabado semi mate que protege la superficie. Su formato de entablonado de largos variados asegura una estructura estable y resistente, ideal para crear ambientes interiores sofisticados y relajantes.',1,'2026-07-13T15:06:45.455+00:00','2026-07-28T20:03:51.079+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvagt0186cjew3dvwj25k','23904','Espacios Interiores','Pisos','Piso Ingenieria','Prefinished','Entablonado','Roble Natural','Semi Mate','MO','Paraguay','Max Core',NULL,NULL,'12.4',NULL,'3',NULL,'127',NULL,'Largo Variado',NULL,'2.74',NULL,'No',62,'U$S',169.88,NULL,'["/23904-1.jpg","/23904-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de ingeniería de Roble Natural destaca por su tono claro y equilibrado con vetas naturales, ideal para crear ambientes luminosos y modernos con un toque de elegancia clásica. Fabricado por Max Core en Paraguay, presenta un espesor de 12.4 mm, una lámina de madera noble de 3 mm y un acabado semi mate que protege la superficie manteniendo su aspecto orgánico. Su diseño en formato entablonado de largos variados ofrece una estética dinámica y acogedora, siendo una solución duradera y de alta estabilidad para espacios interiores.',1,'2026-07-13T15:06:45.822+00:00','2026-07-28T20:03:51.596+00:00',NULL,'Primera',0);
