INSERT INTO pisos_madera VALUES('cmrjcvd6q018xcjewaed7bb1z','25190','Espacios Interiores','Pisos','Piso Ingenieria','Prefinished','Entablonado','Chene Dore','Mate','A mano','China','Max Core',NULL,NULL,'15',NULL,'4',NULL,'240',NULL,'2200',NULL,'2.11',NULL,'Si',85,'U$S',179.35,NULL,'["/25190-1.jpg","/25190-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de ingeniería de Chene Dore ofrece una estética sofisticada y natural con un acabado mate y terminación a mano que realza la textura de la madera. Fabricado por Max Core en China, posee un espesor total de 15 mm con una generosa lámina noble de 4 mm, garantizando durabilidad y resistencia. Su formato de entablonado ancho de 240 mm y biselado perimetral aporta amplitud y un carácter distintivo a cualquier ambiente interior.',1,'2026-07-13T15:06:49.346+00:00','2026-07-28T20:03:56.607+00:00',NULL,'Primera',0);
