INSERT INTO pisos_madera VALUES('cmrjcvdtl0193cjew5tsva4uw','100001','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Lapacho','Natural','Macizo','Paraguay','Primera',NULL,NULL,'20',NULL,NULL,NULL,'4',NULL,'Largo Variado',NULL,NULL,NULL,'No',91,'U$S',NULL,NULL,'["/100001-1.jpg","/100001-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Lapacho de Primera calidad, originario de Paraguay, ofrece una estética clásica, cálida y de gran distinción, con tonalidades que van desde el marrón amarillento al rojizo y vetas poco marcadas. Con un espesor de 1 pulgada y un ancho de 4 pulgadas, presenta un formato de entablonado de largos variados en su estado natural (sin terminar), ideal para ser pulido y terminado en obra. El lapacho es una de las maderas más duras, pesadas y resistentes del mundo, garantizando una excelente estabilidad ante el alto tránsito y una durabilidad excepcional para ambientes interiores.',1,'2026-07-13T15:06:50.169+00:00','2026-07-28T20:03:57.764+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcve610196cjew9kn56xp2','100002','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Lapacho','Natural','Macizo','Paraguay','Primera',NULL,NULL,'20',NULL,NULL,NULL,'5',NULL,'Largo Variado',NULL,NULL,NULL,'No',101,'U$S',NULL,NULL,'["/100002-1.jpg","/100002-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Lapacho, fabricado en Paraguay con calidad de Primera, ofrece una excepcional resistencia y durabilidad natural ante el desgaste. Con un espesor de 1 pulgada, un ancho de 5 pulgadas y formato de entablonado en largos variados, presenta un acabado natural que resalta la elegancia y calidez de sus vetas, siendo una opción robusta e ideal para brindar distinción a ambientes interiores de alto tráfico.',1,'2026-07-13T15:06:50.618+00:00','2026-07-28T20:03:58.355+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvegu0199cjeww9bvd7t1','100003','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Lapacho','Natural','Macizo','Paraguay','Primera',NULL,NULL,'15',NULL,NULL,NULL,'3',NULL,'Largo Variado',NULL,NULL,NULL,'No',50,'U$S',NULL,NULL,'["/100003-1.jpg","/100003-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Lapacho de primera calidad, proveniente de Paraguay, ofrece una estética natural y atemporal, ideal para aportar calidez y robustez a cualquier ambiente interior. Con un espesor de 3/4 de pulgada y un ancho de 3 pulgadas, se presenta en formato entablonado de largos variados y sin bisel. Al ser un producto sin terminar (unfinished), permite realizar el pulido y acabado final en obra, garantizando una superficie extremadamente resistente, duradera y con el carácter auténtico de la madera noble.',1,'2026-07-13T15:06:51.006+00:00','2026-07-28T20:03:59.042+00:00',NULL,'Primera',0);
