INSERT INTO pisos_madera VALUES('cmrjcvf26019fcjewv1a8k038','100005','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Lapacho','Natural','Macizo','Paraguay','Comercial',NULL,NULL,'20',NULL,NULL,NULL,'3',NULL,'Largo Variado',NULL,NULL,NULL,'Si',70,'U$S',NULL,NULL,'["/100005-1.jpg","/100005-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Lapacho, de calidad Comercial y origen paraguayo, ofrece una estética natural con un acabado natural y terminación maciza. Con un espesor de 1 pulgada y un ancho de 3 pulgadas, se presenta en un formato de entablonado con largos variados. Su diseño incorpora bisel, aportando un toque distintivo, y es una opción de gran resistencia, durabilidad y calidez, ideal para crear ambientes interiores sofisticados.',1,'2026-07-13T15:06:51.774+00:00','2026-07-28T20:04:00.915+00:00',NULL,'Comercial',0);
