INSERT INTO pisos_madera VALUES('cmrjcvfn8019lcjew6a2g9bz0','100007','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Kurupayra','Natural','Macizo','Paraguay','Primera',NULL,NULL,'20',NULL,NULL,NULL,'4',NULL,'Largo Variado',NULL,NULL,NULL,'No',45,'U$S',NULL,NULL,'["/100007-1.jpg","/100007-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso macizo de madera de Kurupayra, de calidad Primera, destaca por su gran dureza, alta densidad y una atractiva tonalidad rojiza oscura con vetas oscuras y bien marcadas, ideales para brindar sofisticación, carácter y alta resistencia a espacios interiores de tráfico intenso. Fabricado en Paraguay, se presenta en un formato de entablonado de largos variados con un espesor de 1 pulgada y un ancho de 4 pulgadas. Al ser un piso natural y sin terminar, ofrece la versatilidad de aplicar el acabado deseado post-instalación, garantizando una superficie sumamente estable, duradera y de gran elegancia clásica.',1,'2026-07-13T15:06:52.532+00:00','2026-07-28T20:04:01.911+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvfx5019ocjewsh9sc7z9','100008','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Cumaru','Natural','Macizo','Brazil','Primera',NULL,NULL,'15',NULL,NULL,NULL,'3',NULL,'Largo Variado',NULL,NULL,NULL,'Si',34,'U$S',NULL,NULL,'["/100008-1.jpg","/100008-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Cumaru destaca por su resistencia y tonalidades cálidas, ideal para aportar elegancia y durabilidad a ambientes interiores [cite: 1]. De selección Primera y origen Brasil, se presenta sin terminar (unfinished) con acabado natural, lo que permite un pulido y laqueado personalizado en obra [cite: 1]. Cuenta con un espesor de 3/4 de pulgada, un ancho de 3 pulgadas y un diseño de entablonado en largos variados con bisel, brindando una apariencia auténtica, sofisticada y de gran calidez estética [cite: 1].',1,'2026-07-13T15:06:52.890+00:00','2026-07-28T20:04:02.402+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvg9a019rcjew9szhhe6z','100009','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Murucatiara','Natural','Macizo','Brazil','Primera',NULL,NULL,'15',NULL,NULL,NULL,'3',NULL,'Largo Variado',NULL,NULL,NULL,'Si',39,'U$S',NULL,NULL,'["/100009-1.jpg","/100009-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Murucatiara (Tigerwood), fabricado con calidad de Primera en Brasil, destaca por sus llamativos contrastes de color marrón rojizo con vetas oscuras que aportan un carácter dinámico, elegante y exclusivo a los espacios interiores. Presenta un espesor de 3/4 de pulgada, un ancho de 3 pulgadas y un formato de entablonado de largos variados que realza su aspecto natural. Con un acabado natural sin terminar (unfinished) y diseño con bisel, es una opción altamente resistente al impacto, duradera y de gran estabilidad que añade una calidez sofisticada y única a cualquier ambiente.',1,'2026-07-13T15:06:53.326+00:00','2026-07-28T20:04:02.885+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvgjt019ucjew0w5m3flb','100010','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Grapia','Natural','Macizo','Brazil','Primera',NULL,NULL,'15',NULL,NULL,NULL,'3',NULL,'Largo Variado',NULL,NULL,NULL,'No',48,'U$S',NULL,NULL,'["/100010-1.jpg","/100010-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Grapia ofrece una apariencia clásica y natural con tonalidades amarillas doradas y marrones claras, ideal para brindar luminosidad y calidez a cualquier ambiente interior. Fabricado en condiciones de primera calidad en Brasil, cuenta con un espesor de 3/4 de pulgada y un ancho de 3 pulgadas. Al presentarse en formato de entablonado unfinished de largos variados, resalta su carácter fuerte y auténtico, permitiendo realizar la terminación directamente en obra para adaptarse a las necesidades estéticas de cada proyecto.',1,'2026-07-13T15:06:53.705+00:00','2026-07-28T20:04:03.326+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvgvg019xcjewmpbm6ujy','100011','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Jatoba','Natural','Macizo','Brazil','Primera',NULL,NULL,'20',NULL,NULL,NULL,'3',NULL,'Largo Variado',NULL,NULL,NULL,'Si',44.5,'U$S',NULL,NULL,'["/100011-1.jpg","/100011-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera de Jatoba ofrece una estética elegante y con personalidad, caracterizada por sus tonos rojizos y vetas expresivas que aportan gran calidez y distinción a cualquier ambiente interior. Fabricado en calidad de Primera en Brasil, se presenta en un formato de madera maciza sin barnizar (al natural) de 1 pulgada de espesor y 3 pulgadas de ancho. Su diseño en formato entablonado de largos variados incluye biselado, lo que resalta la originalidad única de cada tabla de madera natural, garantizando una superficie de alta durabilidad y gran resistencia para usos intensivos.',1,'2026-07-13T15:06:54.125+00:00','2026-07-28T20:04:03.779+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvh9n01a0cjew733onu5d','100012','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Jatoba','Natural','Macizo','Brazil','Primera',NULL,NULL,'20',NULL,NULL,NULL,'6',NULL,'Largo Variado',NULL,NULL,NULL,'Si',86,'U$S',NULL,NULL,'["/100012-1.jpg","/100012-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera de Jatoba, de calidad Primera y proveniente de Brasil, destaca por su excelente durabilidad, gran dureza y una estética distinguida de tonalidad rojiza con brillo natural. Con un espesor de 1 pulgada, un ancho de 6 pulgadas y un formato macizo de entablonado en largos variados, cuenta con un diseño biselado que aporta un toque moderno y sofisticado. Es una opción de alta resistencia al desgaste, ideal para crear ambientes interiores cálidos, lujosos y duraderos.',1,'2026-07-13T15:06:54.635+00:00','2026-07-28T20:04:04.232+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvhoh01a3cjew3w4li15x','100013','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Grapia','Natural','Macizo','Brazil','Primera',NULL,NULL,'20',NULL,NULL,NULL,'3',NULL,'Largo Variado',NULL,NULL,NULL,'No',51,'U$S',NULL,NULL,'["/100013-1.jpg","/100013-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Grapia destaca por su tonalidad clara y su gran resistencia natural, siendo ideal para aportar calidez y elegancia a ambientes interiores [cite: 1]. Al ser un producto unfinished (sin terminar), permite aplicar el acabado final deseado directamente en obra [cite: 1]. Proveniente de Brasil con calidad de Primera, cuenta con un espesor de 1 pulgada y un ancho de 3 pulgadas [cite: 1]. Su diseño en formato de entablonado de largos variados sin bisel asegura una superficie continua, robusta y de alta durabilidad [cite: 1].',1,'2026-07-13T15:06:55.169+00:00','2026-07-28T20:04:04.671+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvi1b01a6cjewtbxmu01n','100014','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Roble Americano','Natural','Macizo','EEUU','Primera',NULL,NULL,'20',NULL,NULL,NULL,'3',NULL,'Largo Variado',NULL,NULL,NULL,'No',198,'U$S',NULL,NULL,'["/100014-1.jpg","/100014-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Roble Americano destaca por su elegancia clásica y gran estabilidad, aportando luminosidad y refinamiento a cualquier ambiente interior. Procedente de EEUU, cuenta con un espesor de 1 pulgada, un ancho de 3 pulgadas y un formato de entablonado de largos variados con acabado natural. Su estructura de madera maciza ofrece una superficie altamente resistente a la abrasión y al desgaste, ideal para quienes buscan una opción duradera y sofisticada.',1,'2026-07-13T15:06:55.631+00:00','2026-07-28T20:04:05.140+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvif001a9cjewiwk65al8','100015','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Roble Americano','Natural','Macizo','EEUU','Primera',NULL,NULL,'20',NULL,NULL,NULL,'4',NULL,'Largo Variado',NULL,NULL,NULL,'No',203,'U$S',NULL,NULL,'["/100015-1.jpg","/100015-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Roble Americano ofrece una elegancia clásica y una extraordinaria dureza, ideal para aportar distinción y calidez a ambientes interiores. Presenta un espesor de 1 pulgada y un ancho de 4 pulgadas con formato de entablonado en largos variados. Con su acabado natural, destaca por sus vetas bien definidas y óptima estabilidad, garantizando una superficie altamente resistente y duradera frente al desgaste.',1,'2026-07-13T15:06:56.124+00:00','2026-07-28T20:04:05.553+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvit601accjewo9ng4fve','100016','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Roble Americano','Natural','Macizo','EEUU','Primera',NULL,NULL,'20',NULL,NULL,NULL,'5',NULL,'Largo Variado',NULL,NULL,NULL,'No',208,'U$S',NULL,NULL,'["/100016-1.jpg","/100016-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Roble Americano destaca por su elegancia clásica, vetas marcadas y una excepcional durabilidad y dureza. Proveniente de EEUU, se presenta sin terminar (unfinished) en un formato entablonado de largos variados, con un espesor de 1 pulgada y un ancho de 5 pulgadas. Es una opción de alta calidad ideal para aportar calidez, distinción y un carácter único a cualquier ambiente interior.',1,'2026-07-13T15:06:56.635+00:00','2026-07-28T20:04:06.003+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvj4301afcjewzxg4gf88','100017','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Roble Americano','Natural','Macizo','EEUU','Primera',NULL,NULL,'20',NULL,NULL,NULL,'6',NULL,'Largo Variado',NULL,NULL,NULL,'No',226,'U$S',NULL,NULL,'["/100017-1.jpg","/100017-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera de Roble Americano destaca por su gran dureza, estabilidad y resistencia a la abrasión, aportando una estética clásica y atemporal a ambientes interiores. Fabricado en Argentina bajo la marca Primera, presenta un formato de entablonado macizo e unfinished con un espesor de 1 pulgada, un ancho de 6 pulgadas y largos variados que realzan sus vetas marcadas y su calidez natural. Es una opción duradera de alta calidad, ideal tanto para uso residencial como comercial.',1,'2026-07-13T15:06:57.027+00:00','2026-07-28T20:04:06.440+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvjfw01aicjewn94dfp1t','100018','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Chevron','Roble Americano','Natural','Macizo','EEUU','Primera',NULL,NULL,'20',NULL,NULL,NULL,'3',NULL,'Largo Fijo',NULL,NULL,NULL,'No',228,'U$S',NULL,NULL,'["/100018-1.jpg","/100018-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Roble Americano ofrece una estética elegante y atemporal con su acabado natural que resalta las vetas y características propias de la madera. Importado de EEUU y comercializado bajo la marca Primera, cuenta con un espesor de 1 pulgada y un ancho de 3 pulgadas. Su diseño en formato Chevron de largo fijo proporciona un patrón geométrico sofisticado, aportando distinción, calidez y una alta durabilidad a cualquier ambiente interior.',1,'2026-07-13T15:06:57.453+00:00','2026-07-28T20:04:07.004+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvjqe01alcjew8v7vp01a','100019','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Chevron','Roble Americano','Natural','Macizo','EEUU','Primera',NULL,NULL,'20',NULL,NULL,NULL,'4',NULL,'Largo Fijo',NULL,NULL,NULL,'No',233,'U$S',NULL,NULL,'["/100019-1.jpg","/100019-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Roble Americano en formato Chevron ofrece una estética clásica y sofisticada, ideal para aportar distinción y luminosidad a cualquier ambiente interior. Procedente de EEUU y seleccionado en calidad Primera, se presenta en un formato de largo fijo con un espesor de 1 pulgada y un ancho de 4 pulgadas, perfecto para crear un patrón geométrico dinámico y elegante. Al ser un producto sin acabar (unfinished) con acabado natural, resalta las vetas bien definidas y el grano expresivo característicos de la especie, garantizando una excelente estabilidad dimensional, alta resistencia al desgaste y una durabilidad excepcional.',1,'2026-07-13T15:06:57.830+00:00','2026-07-28T20:04:07.439+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvk0q01aocjewr82dbcdm','100020','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Chevron','Roble Americano','Natural','Macizo','EEUU','Primera',NULL,NULL,'20',NULL,NULL,NULL,'5',NULL,'Largo Fijo',NULL,NULL,NULL,'No',239,'U$S',NULL,NULL,'["/100020-1.jpg","/100020-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Roble Americano destaca por su robustez excepcional y elegancia atemporal, ideal para jerarquizar ambientes interiores. Al ser un producto unfinished (sin terminar), se presenta en su estado natural para ser acabado en obra según la preferencia del cliente. Proveniente de EEUU en calidad Primera, posee un importante espesor de 1 pulgada, un ancho de 5 pulgadas y un diseño en formato Chevron de largo fijo que aporta un patrón geométrico sofisticado, dinámico y de gran distinción.',1,'2026-07-13T15:06:58.202+00:00','2026-07-28T20:04:07.904+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvkcn01arcjewigh62vsm','100021','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Chevron','Roble Americano','Natural','Macizo','EEUU','Primera',NULL,NULL,'20',NULL,NULL,NULL,'6',NULL,'Largo Fijo',NULL,NULL,NULL,'No',260,'U$S',NULL,NULL,'["/100021-1.jpg","/100021-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Roble Americano destaca por su elegancia clásica, extraordinaria dureza y alta durabilidad, siendo ideal para aportar distinción y calidez a cualquier ambiente. Proveniente de EEUU, se presenta sin acabar (unfinished) con un espesor de 1 pulgada y un ancho de 6 pulgadas. Su diseño en patrón Chevron de largo fijo proporciona una estética geométrica sofisticada, dinámica y de gran estabilidad dimensional, convirtiéndolo en una opción exclusiva y resistente para interiores.',1,'2026-07-13T15:06:58.631+00:00','2026-07-28T20:04:08.365+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvkn001aucjewyng08l1y','100022','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Tahuari','Natural','Macizo','Brazil','Primera',NULL,NULL,'15',NULL,NULL,NULL,'3',NULL,'Largo Variado',NULL,NULL,NULL,'No',60,'U$S',NULL,NULL,'["/100022-1.jpg","/100022-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso macizo de Tahuari ofrece una estética atractiva con un color marrón rojizo y un hermoso grano, ideal para proyectos de construcción y decoración en ambientes interiores. Fabricado en calidad de Primera en Brasil, presenta un espesor de 3/4 de pulgada y un ancho de 3 pulgadas, garantizando una alta densidad, resistencia y durabilidad. Su formato de entablonado con largos variados y acabado natural aporta un toque de distinción, elegancia y calidez sin igual a cualquier espacio.',1,'2026-07-13T15:06:59.004+00:00','2026-07-28T20:04:08.830+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvky001axcjew8wxl6xf7','100023','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Viraro','Natural','Macizo','Paraguay','Primera',NULL,NULL,'20',NULL,NULL,NULL,'4',NULL,'Largo Variado',NULL,NULL,NULL,'No',89,'U$S',NULL,NULL,'["/100023-1.jpg","/100023-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso macizo de Viraró ofrece una estética clásica y cálida, con tonalidades rojizas y vetas marcadas que brindan carácter a cualquier ambiente interior. Fabricado en Paraguay con calidad de Primera, posee un espesor de 1 pulgada, un ancho de 4 pulgadas y un formato entablonado de largos variados que asegura una instalación tradicional y robusta. Es un producto natural sin terminar, reconocido por su gran dureza, estabilidad dimensional y notable resistencia al desgaste, ideal para jerarquizar espacios residenciales o comerciales.',1,'2026-07-13T15:06:59.400+00:00','2026-07-28T20:04:09.293+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvl9i01b0cjewea9a3lga','100024','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Guayubira','Natural','Macizo','Argentina','Primera',NULL,NULL,'20',NULL,NULL,NULL,'4',NULL,'Largo Variado',NULL,NULL,NULL,'No',47,'U$S',NULL,NULL,'["/100024-1.jpg","/100024-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Guayubira destaca por su veta única y su llamativa tonalidad que combina tonos oscuros y amarillentos, aportando un gran carácter y alto impacto visual. Fabricado en Argentina con calidad de primera, se presenta en un formato de entablonado de largos variados con un espesor de 1 pulgada y un ancho de 4 pulgadas. Al ser una madera dura, pesada y altamente resistente al desgaste, es una opción sumamente estable y duradera ideal para proyectos sofisticados. Su acabado natural sin bisel resalta la pureza y nobleza de la madera maciza, requiriendo su posterior pulido y laqueado en obra.',1,'2026-07-13T15:06:59.815+00:00','2026-07-28T20:04:09.778+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvllb01b3cjewi52fx5rc','100025','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Entablonado','Guayubira','Natural','Macizo','Argentina','Primera',NULL,NULL,'20',NULL,NULL,NULL,'6',NULL,'Largo Variado',NULL,NULL,NULL,'No',55,'U$S',NULL,NULL,'["/100025-1.jpg","/100025-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Guayubira se presenta al natural y sin terminar (unfinished), ideal para aportar la resistencia y autenticidad de la madera real a ambientes interiores. Fabricado en Argentina bajo la selección de Primera calidad, cuenta con un espesor de 1 pulgada y un ancho de 6 pulgadas. Su formato de entablonado con largos variados ofrece una estética robusta, tradicional y de gran calidez, siendo una opción duradera y de alta calidad para personalizar con el acabado deseado en obra.',1,'2026-07-13T15:07:00.239+00:00','2026-07-28T20:04:10.219+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvlxe01b6cjewd77o30q7','100026','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Parquet','Incienso Pardo','Natural','Macizo','Argentina','Primera',NULL,NULL,'10',NULL,NULL,NULL,'3',NULL,'300',NULL,NULL,NULL,'No',35,'U$S',NULL,NULL,'["/100026-1.jpg","/100026-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Incienso Pardo, en formato de parquet, destaca por su tonalidad castaña que se torna paulatinamente parda con vetas bien marcadas y una textura fina y homogénea. Fabricado en Argentina, cuenta con un espesor de 1/2 pulgada y un ancho de 3 pulgadas, presentándose en un formato de largo de 300 mm sin bisel. Es una opción de madera muy dura, pesada y de gran estabilidad, ideal para aportar elegancia, calidez y un agradable aroma natural a los ambientes interiores.',1,'2026-07-13T15:07:00.674+00:00','2026-07-28T20:04:10.624+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvmkv01b9cjew2xjgpogy','100027','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Parquet','Guayacan','Natural','Macizo','Argentina','Primera',NULL,NULL,'15',NULL,NULL,NULL,'4',NULL,'300',NULL,NULL,NULL,'No',19.2,'U$S',NULL,NULL,'["/100027-1.jpg","/100027-2.jpg"]',NULL,NULL,NULL,NULL,'I''m still learning and can''t help with that. Do you need help with anything else?',1,'2026-07-13T15:07:01.519+00:00','2026-07-28T20:04:11.103+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvn1501bccjewec1kskf5','100028','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Parquet','Sirari','Natural','Macizo','Paraguay','Primera',NULL,NULL,'15',NULL,NULL,NULL,'4',NULL,'300',NULL,NULL,NULL,'No',19.2,'U$S',NULL,NULL,'["/100028-1.jpg","/100028-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera de Sirari aporta un toque de modernidad con su color colorado y uniforme, siendo perfecto para quienes buscan una estética contemporánea en ambientes interiores. Fabricado con calidad de Primera en Paraguay, se presenta en formato de parquet macizo de 3/4 pulgadas de espesor, 4 pulgadas de ancho y un largo fijo de 300 mm. Ofrece un acabado natural, una estructura sólida sin bisel y una excelente resistencia para diversos estilos de decoración.',1,'2026-07-13T15:07:02.106+00:00','2026-07-28T20:04:11.524+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvnim01bfcjewnaeiuxl2','100029','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Parquet','Sirari','Natural','Macizo','Paraguay','Primera',NULL,NULL,'15',NULL,NULL,NULL,'3',NULL,'250',NULL,NULL,NULL,'No',19.2,'U$S',NULL,NULL,'["/100029-1.jpg","/100029-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera maciza de Sirari, de calidad Primera y procedencia paraguaya, ofrece una superficie natural ideal para aportar calidez y distinción a ambientes interiores. Con un espesor de 3/4 de pulgada, un ancho de 3 pulgadas y un largo de 250 mm, se presenta en un formato de parquet tradicional sin bisel. Es una opción sumamente duradera, resistente y sofisticada que resalta la belleza clásica y orgánica de la madera genuina.',1,'2026-07-13T15:07:02.734+00:00','2026-07-28T20:04:11.942+00:00',NULL,'Primera',0);
INSERT INTO pisos_madera VALUES('cmrjcvnwj01bicjewt40cl2pe','100030','Espacios Interiores','Pisos','Pisos de Madera','Unfinished','Parquet','Sirari','Natural','Macizo','Paraguay','Primera',NULL,NULL,'15',NULL,NULL,NULL,'5',NULL,'250',NULL,NULL,NULL,'No',19.2,'U$S',NULL,NULL,'["/100030-1.jpg","/100030-2.jpg"]',NULL,NULL,NULL,NULL,'Este piso de madera de Sirari destaca por su acabado natural y estructura maciza, ideal para aportar calidez, resistencia y elegancia a cualquier ambiente interior. Fabricado bajo exigentes estándares de calidad (Primera) en Paraguay, posee un espesor de 3/4 de pulgada y un ancho de 5 pulgadas. Su formato de Parquet con un largo de 250 mm asegura una instalación clásica, estable y duradera, resaltando la belleza orgánica y las vetas propias de la madera.',1,'2026-07-13T15:07:03.236+00:00','2026-07-28T20:04:12.388+00:00',NULL,'Primera',0);
INSERT INTO decks VALUES('cmrjcvohg01blcjewfobw4oq8','22550','Espacios Exterior','Deck','WPC','Max Core','Noble','Fresno Nordico','25',NULL,'140',NULL,'2900',NULL,'0.41',NULL,15.58,38,5.372413793,'U$S','["/22550-1.jpg","/22550-2.jpg","/22550-3.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Fresno Nórdico de la línea Noble de MaxCore es un revestimiento para exteriores de tono claro con una veta fina que recrea fielmente la estética de la madera nórdica. Fabricado con un compuesto de polímeros y fibras de madera, es altamente resistente a la intemperie, al sol y a las temperaturas extremas, destacándose por ser un producto 100% libre de mantenimiento que no requiere lijado ni barnizado.\n\nDebido a su diseño contemporáneo que aporta amplitud visual, se sugiere su uso para jerarquizar espacios exteriores como terrazas, galerías, balcones, quinchos o bordes de piscinas. Puede instalarse sobre diversas superficies, incluyendo contrapisos, carpetas lisas o estructuras de madera.','\n',char(10)),1,'2026-07-13T15:07:03.988+00:00','2026-07-28T20:04:13.147+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvosq01bocjewmcn2twu3','25549','Espacios Exterior','Deck','WPC','Max Core','Noble','Nogal Tabaco','25',NULL,'140',NULL,'2900',NULL,'0.41',NULL,15.58,38,5.372413793,'U$S','["/25549-1.jpg","/25549-2.jpg","/25549-3.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Nogal Tabaco de la línea Noble de MaxCore es un revestimiento para exteriores de tono oscuro y profundo con una veta pronunciada que aporta calidez y elegancia. Fabricado con un compuesto de polímeros y fibras de madera, es altamente resistente a la intemperie, al sol y a la humedad, destacándose por ser un producto de bajo mantenimiento que no requiere lijado ni barnizado.\n\nDebido a su diseño contemporáneo y presencia visual, se sugiere su uso para jerarquizar espacios exteriores como terrazas, galerías, balcones o bordes de piscinas. Puede instalarse sobre diversas superficies utilizando grampas ocultas, lo que garantiza una estética limpia y estable para proyectos residenciales de alta calidad.','\n',char(10)),1,'2026-07-13T15:07:04.395+00:00','2026-07-28T20:04:13.638+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvp3k01brcjewm5d681ph','23023','Espacios Exterior','Deck','WPC','Max Core','Noble','Roble Clasico','25',NULL,'140',NULL,'2900',NULL,'0.41',NULL,13.366,32.6,4.608965517,'U$S','["/23023-1.jpg","/23023-2.jpg","/23023-3.jpg"]',NULL,NULL,NULL,NULL,'El Deck WPC Roble Clásico de la línea Noble de MaxCore es un revestimiento para exteriores que combina madera natural y polímeros para ofrecer una estética de madera tradicional sin mantenimiento. Con un espesor de 25 mm y dimensiones de 14 cm x 2.90 m, presenta un tono medio y veta natural altamente resistente a la intemperie, el agua y los rayos UV. Es una solución duradera y antideslizante ideal para terrazas, galerías o bordes de piscinas, ya que no requiere lijado ni barnizado. Su instalación es rápida y sencilla, apta para diversas superficies exteriores.',1,'2026-07-13T15:07:04.784+00:00','2026-07-28T20:04:14.153+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvpdr01bucjewi51p33nj','22548','Espacios Exterior','Deck','WPC','Max Core','Noble','Roble Gris','25',NULL,'140',NULL,'2900',NULL,'0.41',NULL,15.58,38,5.372413793,'U$S','["/22548-1.jpg","/22548-2.jpg","/22548-3.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Roble Gris de la línea Noble de MaxCore es un revestimiento para exteriores de tono gris natural con una veta moderada, ideal para proyectos residenciales modernos y minimalistas. Fabricado con un compuesto de fibras de madera y polímeros, ofrece la estética de la madera con una alta resistencia a la intemperie, a los rayos UV y a la humedad. Es un producto duradero y de bajo mantenimiento que no requiere lijado, barnizado ni sellado.\n\nPor su diseño contemporáneo que combina con superficies de hormigón o tonos neutros, es la opción más elegida para jerarquizar terrazas, patios y jardines. Su instalación es sencilla y puede realizarse sobre diversas estructuras base, siendo apto para áreas de alto tránsito y seguro para caminar descalzo gracias a su superficie antideslizante.','\n',char(10)),1,'2026-07-13T15:07:05.152+00:00','2026-07-28T20:04:14.603+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvpoe01bxcjewfrybqfse','23581','Espacios Exterior','Deck','WPC','Max Core','Noble','Roble Natural','25',NULL,'140',NULL,'2900',NULL,'0.41',NULL,15.58,38,5.372413793,'U$S','["/23581-1.jpg","/23581-2.jpg","/23581-3.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Roble Natural de la línea Noble de MaxCore es un revestimiento para exteriores de tono cálido y veta natural que recrea la estética de la madera. Fabricado con un compuesto de fibras de madera y polímeros, es altamente resistente a la intemperie, al agua y a los insectos, destacándose por ser un producto 100% libre de mantenimiento que no requiere pintura ni sellado.\n\nDebido a su diseño que combina bien con la vegetación, se sugiere su uso para jerarquizar espacios como galerías, terrazas y remodelaciones de exterior. Puede instalarse sobre estructuras de soporte, proporcionando una superficie nivelada, uniforme y antideslizante.','\n',char(10)),1,'2026-07-13T15:07:05.535+00:00','2026-07-28T20:04:15.070+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvpzs01c0cjewoxwpdxi5','19853','Espacios Exterior','Deck','WPC','Max Core','Prestigio','Teak','22',NULL,'138',NULL,'2900',NULL,'0.4',NULL,24,60,8.275862069,'U$S','["/19853-1.jpg","/19853-2.jpg"]',NULL,NULL,NULL,NULL,'El Deck WPC Teak de la línea Prestigio de MaxCore es un revestimiento premium para exteriores que recrea fielmente la estética de la madera tropical con una veta pronunciada y un tono cálido. Fabricado con un compuesto de polímeros y fibras de madera de alta densidad, este producto es 100% libre de mantenimiento, resistente a la intemperie, a los rayos UV y a temperaturas extremas. Su perfil de 22 mm de espesor está diseñado para proyectos de alta exposición solar y humedad, siendo ideal para terrazas, piscinas, galerías o balcones. Al ser un material sintético, no se deforma, no se astilla y ofrece una superficie antideslizante segura para pies descalzos. Puede instalarse sobre diversas superficies como contrapisos, carpetas lisas o estructuras de madera.',1,'2026-07-13T15:07:05.945+00:00','2026-07-28T20:04:15.480+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvqcm01c3cjew0y5ly98k','19852','Espacios Exterior','Deck','WPC','Max Core','Prestigio','Ipe','22',NULL,'138',NULL,'2900',NULL,'0.4',NULL,18.4,46,6.344827586,'U$S','["/19852-2.jpg"]',NULL,NULL,NULL,NULL,'El Deck WPC Ipe de la línea Prestigio de MaxCore es un revestimiento para exteriores de tono marrón que combina la estética natural de la madera con la durabilidad de los polímeros. Con dimensiones de 138 mm de ancho, 2900 mm de largo y un espesor de 22 mm, ofrece un rendimiento de 0.40 m2 por tabla. Fabricado con fibras de madera y plástico reciclado, es un producto ecológico, 100% libre de mantenimiento, resistente al agua, a los rayos UV y a las altas temperaturas. Su diseño antideslizante y de alta resistencia lo hace ideal para jerarquizar espacios como terrazas, balcones, quinchos o bordes de piscinas, pudiendo instalarse sobre contrapisos o estructuras de madera.',1,'2026-07-13T15:07:06.407+00:00','2026-07-28T20:04:15.906+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvqo801c6cjewil6j8r1t','22875','Espacios Exterior','Deck','WPC','Max Core','Bulk','Ambar','25',NULL,'147',NULL,'2900',NULL,'0.43',NULL,14.018,32.6,4.833793103,'U$S','["/22875-1.jpg","/22875-2.jpg","/22875-3.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Ambar de la línea Bulk de MaxCore es un revestimiento para exteriores de tonalidad cálida diseñado para brindar durabilidad y estética natural. Fabricado con un compuesto de polímeros y fibras de madera, ofrece una alta resistencia a la intemperie, los rayos UV y las variaciones térmicas, manteniendo su color y forma sin necesidad de lijado ni barnizado.\n\nPor su robustez y acabado, es ideal para superficies de uso frecuente como terrazas, galerías, bordes de piscinas y balcones. Su instalación es versátil, adaptándose a estructuras de madera, contrapisos o carpetas lisas, garantizando un espacio exterior elegante y de bajo mantenimiento.','\n',char(10)),1,'2026-07-13T15:07:06.824+00:00','2026-07-28T20:04:16.327+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvqy701c9cjewkj78c9n7','24942','Espacios Exterior','Deck','WPC','Max Core','Reversible','Silver Grey Light Grey','23',NULL,'138',NULL,'3000',NULL,'0.4',NULL,15.6,39,5.2,'U$S','["/24942-1.jpg","/24942-2.jpg","/24942-3.jpg"]',NULL,NULL,NULL,NULL,'El Deck WPC Silver Grey / Light Grey de la línea Reversible de MaxCore es un revestimiento para exteriores que ofrece versatilidad estética gracias a su diseño de doble cara en tonos grises modernos. Fabricado con un compuesto de polímeros y fibras de madera, este material es altamente resistente a la intemperie, los rayos UV y las temperaturas extremas, garantizando una larga durabilidad sin necesidad de lijado ni barnizado. Por ser un producto 100% libre de mantenimiento y con un estilo contemporáneo, es ideal para transformar espacios como terrazas, galerías, balcones o bordes de piscinas. Su instalación es sencilla y puede realizarse sobre diversas superficies, desde carpetas de cemento hasta estructuras de madera.',1,'2026-07-13T15:07:07.183+00:00','2026-07-28T20:04:16.816+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvr8c01cccjewpk3abiye','25044','Espacios Exterior','Deck','WPC','Max Core','Reversible','Light Teak Walnut','21',NULL,'140',NULL,'2700',NULL,'0.38',NULL,23.37,61.5,8.655555556,'U$S','["/25044-1.jpg","/25044-2.jpg","/25044-3.jpg"]',NULL,NULL,NULL,NULL,'El Deck WPC Light Teak Walnut de la línea Reversible de MaxCore es un revestimiento para exteriores de doble cara que ofrece versatilidad estética al combinar dos tonos en una misma tabla. Fabricado con un compuesto de fibras de madera natural y polímeros plásticos reciclados, es un producto ecológico, duradero y altamente resistente a la humedad, la putrefacción y las altas temperaturas. Su diseño de 21 mm de espesor es ideal para jerarquizar espacios como terrazas, galerías y bordes de piscinas, destacándose por ser 100% libre de mantenimiento al no requerir lijado ni barnizado.',1,'2026-07-13T15:07:07.549+00:00','2026-07-28T20:04:17.286+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvriz01cfcjewq3rwdkjj','22864','Espacios Exterior','Deck','WPC','Max Core','Reversible','Gris Plata Gris Cenisa','22',NULL,'138',NULL,'2900',NULL,'0.4',NULL,18.6,46.5,6.413793103,'U$S','["/22864-1.jpg","/22864-2.jpg","/22864-3.jpg"]',NULL,NULL,NULL,NULL,'El Deck WPC Gris Plata Gris Cenisa de la línea Reversible de MaxCore es un revestimiento de doble cara diseñado para exteriores, que combina un compuesto de polímeros y fibras de madera para ofrecer alta resistencia a la intemperie, rayos UV y humedad. Con un acabado que simula madera envejecida, este producto es 100% libre de mantenimiento, evitando la necesidad de lijado o barnizado. Su versatilidad permite la instalación en terrazas, balcones, galerías o bordes de piscinas, ya sea sobre contrapisos o estructuras de madera.',1,'2026-07-13T15:07:07.931+00:00','2026-07-28T20:04:17.706+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvrtu01cicjewuhdvh15w','22865','Espacios Exterior','Deck','WPC','Max Core','Reversible','Gris Grafito Fresno Nordico','22',NULL,'138',NULL,'2900',NULL,'0.4',NULL,24,60,8.275862069,'U$S','["/22865-1.jpg","/22865-2.jpg","/22865-3.jpg"]',NULL,NULL,NULL,NULL,'El Deck WPC Gris Grafito / Fresno Nórdico de la línea Reversible de MaxCore es un revestimiento bicapa diseñado para exteriores que ofrece un efecto visual cambiante y decorativo. Con un espesor de 22 mm, este producto combina polímeros y fibras naturales para brindar una alta resistencia a condiciones meteorológicas severas, rayos UV, agua e insectos, siendo una opción duradera y ecológica. Su principal característica es que es 100% libre de mantenimiento, eliminando la necesidad de lijado o barnizado, y es ideal para jerarquizar espacios como terrazas, patios y jardines.',1,'2026-07-13T15:07:08.323+00:00','2026-07-28T20:04:18.186+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvs4e01clcjewkjdxbf9m','23534','Espacios Exterior','Deck','WPC','Max Core','Reversible','Roble Marron Blanco Puro','22',NULL,'138',NULL,'2900',NULL,'0.4',NULL,18.6,46.5,6.413793103,'U$S','["/23534-1.jpg","/23534-2.jpg","/23534-3.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Roble Marrón Blanco Puro de la línea Reversible de MaxCore es un revestimiento bicolor de la colección Camaleón, diseñado para ofrecer versatilidad estética con un tono roble marrón de un lado y blanco puro del otro. Fabricado con un compuesto de polímeros y fibras de madera, este perfil de 22 mm destaca por su acabado mate y un diseño decorativo ideal para lograr contrastes visuales en terrazas y áreas exteriores. Al igual que otros productos de la marca, es altamente resistente a la humedad, a las temperaturas extremas y a los rayos UV, garantizando una durabilidad superior sin necesidad de lijado ni barnizado.\n\nGracias a su superficie antideslizante y su composición eco-friendly elaborada con materiales reciclados, es una opción segura y sostenible para jerarquizar galerías, balcones o bordes de piscinas. Su instalación es sencilla y permite una renovación estética paulatina similar al envejecimiento natural de la madera, manteniendo la integridad del material frente al clima variable.','\n',char(10)),1,'2026-07-13T15:07:08.702+00:00','2026-07-28T20:04:18.638+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvsez01cocjewd0tuyq4q','24162','Espacios Exterior','Deck','WPC','Max Core','Oval','Marron Coco','24',NULL,'142',NULL,'2900',NULL,'0.42',NULL,13.692,32.6,4.72137931,'U$S','["/24162-1.jpg","/24162-2.jpg"]',NULL,NULL,NULL,NULL,'El Deck WPC Marrón Coco de la línea Oval de MaxCore es un revestimiento para exteriores con un perfil redondeado diseñado específicamente para brindar seguridad y estética en bordes de piscinas y escalones. Fabricado con materiales reciclados, es un producto eco-friendly altamente resistente a la humedad, la putrefacción y el calor, lo que evita deformaciones en climas exigentes. Al igual que otros productos de la marca, destaca por ser 100% libre de mantenimiento, ofreciendo una durabilidad superior sin necesidad de lijado ni barnizado.',1,'2026-07-13T15:07:09.084+00:00','2026-07-28T20:04:19.067+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvsq201crcjewdrjkqavr','24161','Espacios Exterior','Deck','WPC','Max Core','Oval','Marron Dorado','24',NULL,'142',NULL,'2900',NULL,'0.42',NULL,13.692,32.6,4.72137931,'U$S','["/24161-1.jpg","/24161-2.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Marrón Dorado de la línea Oval de MaxCore es un revestimiento alveolar y liviano para exteriores, diseñado para ser eficiente y resistente en proyectos de gran superficie. Fabricado con un compuesto de polímeros y fibras de madera, ofrece una estética elegante con la durabilidad del material sintético, siendo altamente resistente a la intemperie, los rayos UV y las temperaturas extremas. Se destaca por ser un producto 100% libre de mantenimiento que no requiere lijado, pintura ni barnizado.\n\nGracias a su diseño robusto, es ideal para jerarquizar espacios como terrazas, galerías, patios o bordes de piscinas, soportando el uso intensivo sin deformarse. Puede instalarse de manera sencilla sobre diversas superficies, incluyendo contrapisos, carpetas lisas o estructuras de madera, ofreciendo una solución ecológica y duradera para climas variables.','\n',char(10)),1,'2026-07-13T15:07:09.482+00:00','2026-07-28T20:04:19.621+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvt0l01cucjewxxwnkp7p','23941','Espacios Exterior','Baldosa deck','WPC','Max Core','Baldosa','Jaspeado','20',NULL,'300',NULL,'300',NULL,'0.09',NULL,2.952,32.8,9.84,'U$S','["/23941-1.jpg","/23941-2.jpg","/23941-3.jpg"]',NULL,NULL,NULL,NULL,'La Baldosa Deck WPC Jaspeado de la línea Baldosa de MaxCore es un revestimiento modular de 300x300 mm diseñado para transformar espacios exteriores con facilidad. Fabricada con un compuesto de polímeros y fibras de madera, ofrece una alta resistencia a la intemperie y a los rayos UV, manteniendo su apariencia sin necesidad de mantenimiento constante como lijado o barnizado. Su acabado jaspeado brinda una estética natural y moderna ideal para renovar de forma práctica terrazas, balcones, patios y bordes de piscina. Gracias a su sistema de encastre, permite una instalación rápida y sencilla sobre superficies niveladas y firmes.',1,'2026-07-13T15:07:09.861+00:00','2026-07-28T20:04:20.216+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvtb001cxcjew6kv785qv','24152','Espacios Exterior','Baldosa deck','WPC','Max Core','Baldosa','Tabaco','20',NULL,'300',NULL,'300',NULL,'0.09',NULL,3.7125,41.25,12.375,'U$S','["/24152-1.jpg","/24152-2.jpg","/24152-3.jpg"]',NULL,NULL,NULL,NULL,'La Baldosa Deck WPC Tabaco de la línea Baldosa de MaxCore es un revestimiento para exteriores de tono oscuro diseñado para una instalación rápida y sencilla mediante un sistema de encastre. Fabricada con un compuesto de polímeros y fibras de madera, ofrece una alta resistencia a la humedad, a la putrefacción y a las temperaturas extremas, siendo un producto ecológico de mantenimiento mínimo que no requiere lijado ni barnizado. Con un formato de 30x30 cm y un espesor de 20 mm, es ideal para renovar terrazas, balcones o bordes de piscinas de manera práctica y estética. Su diseño funcional garantiza una larga vida útil y estabilidad dimensional en diversos entornos exteriores.',1,'2026-07-13T15:07:10.237+00:00','2026-07-28T20:04:20.810+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvtlf01d0cjewgt2l9i53','24153','Espacios Exterior','Baldosa deck','WPC','Max Core','Baldosa','Roble Gris','20',NULL,'300',NULL,'300',NULL,'0.09',NULL,3.7125,41.25,12.375,'U$S','["/24153-1.jpg","/24153-2.jpg","/24153-3.jpg"]',NULL,NULL,NULL,NULL,'La Baldosa Deck WPC Roble Gris de la línea Baldosa de MaxCore es una solución práctica para exteriores que combina la estética de la madera gris con un sistema de encastre fácil de instalar. Fabricada con un compuesto de polímeros y fibras de madera, es un producto 100% libre de mantenimiento, resistente a la humedad, a la putrefacción y a las altas temperaturas, lo que evita deformaciones comunes en la madera natural. Su diseño de 30x30 cm es ideal para renovar rápidamente espacios como terrazas, balcones, patios o bordes de piscinas, pudiendo aplicarse sobre superficies niveladas como carpetas o contrapisos. Al ser eco-friendly, utiliza materiales reciclados conservando una apariencia moderna y minimalista que integra perfectamente con diseños neutros.',1,'2026-07-13T15:07:10.611+00:00','2026-07-28T20:04:21.317+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvtvs01d3cjewoesi824h','22318','Espacios Exterior','Baldosa deck','WPC','Max Core','Baldosa','Roble Clasico','20',NULL,'300',NULL,'300',NULL,'0.09',NULL,3.7125,41.25,12.375,'U$S','["/22318-1.jpg","/22318-2.jpg","/22318-3.jpg"]',NULL,NULL,NULL,NULL,'La Baldosa Deck WPC Roble Clásico de la línea Baldosa de MaxCore es un revestimiento para exteriores de tono tradicional que recrea la estética de la madera clásica. Fabricada con un compuesto de polímeros y fibras de madera, ofrece alta resistencia a la intemperie, al sol y a temperaturas extremas, siendo un producto libre de mantenimiento que no requiere lijado ni barnizado. Gracias a su formato de baldosa de 300x300 mm, permite una instalación rápida y sencilla, ideal para renovar y jerarquizar espacios como terrazas, balcones, galerías o bordes de piscinas sobre superficies niveladas.',1,'2026-07-13T15:07:10.985+00:00','2026-07-28T20:04:21.824+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvu7601d6cjewud5moku8','22551','Espacios Exterior','Accesorios','WPC','Max Core','Accesorios','Alfajias','20',NULL,'40',NULL,'2900',NULL,NULL,NULL,8.4,NULL,NULL,'U$S','["/22551-1.jpg"]',NULL,NULL,NULL,NULL,'Las Alfajias de WPC de la línea Accesorios de MaxCore son perfiles de montaje diseñados como base estructural para la instalación de decks en exteriores. Fabricadas con un compuesto de fibras de madera y polímeros, ofrecen alta resistencia a la humedad, la intemperie y temperaturas extremas sin deformarse ni generar hongos. Es un producto de bajo mantenimiento que no requiere pintura ni barnizado, ideal para facilitar el montaje de diversos revestimientos sobre superficies niveladas.',1,'2026-07-13T15:07:11.394+00:00','2026-07-28T20:04:22.340+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvuhq01d9cjewcsg2pppf','19848','Espacios Exterior','Accesorios','WPC','Max Core','Accesorios','Tapa 50 mm Teak','10',NULL,'50',NULL,'2900',NULL,NULL,NULL,15.1,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'La Tapa de 50 mm Teak de la línea de Accesorios de MaxCore es un complemento de WPC diseñado para brindar una terminación estética y funcional en proyectos de deck. Fabricada con un compuesto de polímeros y fibras de madera, presenta un acabado en tono Teak que armoniza con los perfiles principales, garantizando alta resistencia a la intemperie y a la exposición solar sin necesidad de mantenimiento. Su diseño permite ocultar bordes y uniones, asegurando un cierre prolijo y duradero en terrazas, galerías o bordes de piscinas. Al igual que el resto de la línea, es resistente a temperaturas extremas y no requiere lijado ni barnizado.',1,'2026-07-13T15:07:11.774+00:00','2026-07-28T20:04:22.961+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvusg01dccjew8r5fyp6m','19847','Espacios Exterior','Accesorios','WPC','Max Core','Accesorios','Tapa 50 mm Ipe','10',NULL,'50',NULL,'2900',NULL,NULL,NULL,15.1,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'La Tapa de 50 mm Ipe de la línea de Accesorios de MaxCore es un complemento de terminación fabricado en WPC, diseñado para brindar un acabado estético y funcional a las instalaciones de deck. Con un espesor de 10 mm y un ancho de 50 mm, este accesorio en tono Ipe permite ocultar cortes y bordes, manteniendo la durabilidad y resistencia a la intemperie características del material. Al igual que los perfiles principales, es libre de mantenimiento y no requiere tratamientos adicionales como lijado o barnizado. Su uso es ideal para perfeccionar los detalles finales en terrazas, bordes de piscinas y galerías.',1,'2026-07-13T15:07:12.160+00:00','2026-07-28T20:04:23.571+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvv2p01dfcjew7naie994','19850','Espacios Exterior','Accesorios','WPC','Max Core','Accesorios','Tapa 138 mm Teak','10',NULL,'138',NULL,'2900',NULL,NULL,NULL,18.5,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'La Tapa WPC 138 mm Teak de la línea Accesorios de MaxCore es un complemento diseñado para brindar una terminación estética y profesional a proyectos de deck en exteriores. Fabricada con un compuesto de polímeros y fibras de madera en tono Teak, ofrece una alta resistencia a la intemperie y a los rayos UV, manteniendo su apariencia sin necesidad de mantenimiento como lijado o barnizado. Su ancho de 138 mm permite cubrir bordes y laterales de forma armoniosa, integrándose perfectamente con tablas de deck de medidas similares. Es ideal para ocultar estructuras de soporte y perfeccionar el acabado visual en terrazas, balcones y bordes de piscinas.',1,'2026-07-13T15:07:12.529+00:00','2026-07-28T20:04:24.085+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvvcs01dicjewt8xtifww','19849','Espacios Exterior','Accesorios','WPC','Max Core','Accesorios','Tapa 138 mm Ipe','10',NULL,'138',NULL,'2900',NULL,NULL,NULL,18.5,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'La Tapa de 138 mm Ipe de la línea Accesorios de MaxCore es un complemento de terminación para decks de WPC diseñado para brindar un acabado estético y profesional. Fabricada con un compuesto de polímeros y fibras de madera en tono Ipe, ofrece una alta resistencia a la intemperie y a los rayos UV sin necesidad de mantenimiento, pintura o barnizado. Su uso principal es el sellado lateral de las tablas de deck, asegurando una apariencia uniforme y protegiendo la estructura de la acumulación de suciedad. Se instala de manera sencilla sobre los bordes de la estructura del deck para ocultar los cortes y las fijaciones.',1,'2026-07-13T15:07:12.892+00:00','2026-07-28T20:04:24.723+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvvnx01dlcjewc0obxw5e','22409','Espacios Exterior','Accesorios','WPC','Max Core','Accesorios','Angulos END Varios Colores','10',NULL,'40',NULL,'40',NULL,NULL,NULL,15.4,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'Los Ángulos END de la línea de Accesorios de MaxCore son piezas de terminación fabricadas en WPC, diseñadas para brindar un acabado estético y profesional a los bordes y esquinas de las instalaciones de deck. Con dimensiones de 40x40 mm y un espesor de 10 mm, estos perfiles son altamente resistentes a la intemperie y no requieren mantenimiento, como lijado o barnizado. Disponibles en varios colores para coordinar con las diferentes líneas de la marca, son ideales para proteger los bordes expuestos y ocultar la estructura interna en terrazas, escalones y perímetros de piscinas.',1,'2026-07-13T15:07:13.293+00:00','2026-07-28T20:04:25.897+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvw1t01docjewlrcj5550','24855','Espacios Exterior','Accesorios','WPC','Max Core','Accesorios','Angulos END Varios Colores','10',NULL,'60',NULL,'60',NULL,NULL,NULL,15.4,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'El Angulo de terminación WPC de MaxCore es un accesorio diseñado para brindar un acabado profesional, prolijo y elegante a proyectos de exterior, como decks y baldosas. Fabricado con un compuesto de polímeros y fibras de madera, este perfil en L es altamente resistente a la intemperie y se utiliza para cubrir bordes, esquinas y uniones. Al ser del mismo material y color que las tablas de deck, garantiza una estética uniforme y duradera sin necesidad de mantenimiento complejo. Es ideal para remates en escalones o encuentros de superficies, asegurando una transición suave y protegida.',1,'2026-07-13T15:07:13.793+00:00','2026-07-28T20:04:26.353+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvwez01drcjew6elnnfkd','18883','Espacios Exterior','Accesorios','WPC','Max Core','Noble','Grampas',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.14,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'Las Grampas de la línea Noble de MaxCore son accesorios de fijación diseñados específicamente para la instalación de sistemas de Deck WPC. Fabricadas con materiales resistentes que aseguran la durabilidad de la estructura al aire libre, estas piezas permiten una sujeción firme y discreta de las tablas, facilitando un acabado profesional y uniforme en terrazas, galerías o perímetros de piscinas sin necesidad de perforaciones visibles en la superficie del deck.',1,'2026-07-13T15:07:14.268+00:00','2026-07-28T20:04:26.893+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvwvg01ducjew3w6oozne','24165','Espacios Exterior','Accesorios','WPC','Max Core','Oval','Grampas',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.14,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'Las grampas de MaxCore para la línea Oval son accesorios fundamentales para la fijación oculta de tablas de deck WPC, permitiendo una instalación funcional y práctica sin tornillos a la vista. Fabricadas en material plástico o metálico, estas grapas son altamente compatibles con decks de madera y compuestos. Se recomienda la utilización de aproximadamente 25 a 32 unidades por cada metro cuadrado de superficie a cubrir para asegurar una sujeción óptima y duradera. Al igual que los perfiles de la marca, son resistentes a la intemperie y no requieren mantenimiento adicional.',1,'2026-07-13T15:07:14.860+00:00','2026-07-28T20:04:27.362+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvx8m01dxcjewzo6op1lp','19851','Espacios Exterior','Accesorios','WPC','Max Core','Prestigio','Grampas',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.14,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'La grampa para Deck WPC de la linea Prestigio de MaxCore es un accesorio de fijacion diseñado para asegurar una instalacion firme, prolija y duradera en tablas de madera plastica. Fabricada en materiales resistentes como acero galvanizado o acero inoxidable, garantiza alta resistencia a la corrosion, la humedad y el transito en exteriores. Su funcion principal es mantener la alineacion y separacion uniforme entre las piezas, permitiendo la dilatacion natural del material sin deformaciones. Al ser un sistema de fijacion oculta, logra un acabado limpio y profesional sin tornillos a la vista en la superficie del deck.',1,'2026-07-13T15:07:15.335+00:00','2026-07-28T20:04:27.817+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvxpq01e0cjew2givwrkh','21261','Espacios Exterior','Accesorios','WPC','Max Core','Bulk','Grampas',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,0.14,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,'Las Grampas de la línea Bulk de MaxCore son accesorios esenciales fabricados en WPC diseñados para la fijación técnica de tablas de deck. Su uso permite una instalación precisa y segura, manteniendo la separación adecuada entre piezas y asegurando la estabilidad del revestimiento exterior. Al ser parte del sistema MaxCore, son resistentes a la corrosión y están diseñadas para complementar la durabilidad y el acabado estético de los proyectos de deck de madera compuesta.',1,'2026-07-13T15:07:15.950+00:00','2026-07-28T20:04:28.257+00:00',NULL,0);
INSERT INTO decks VALUES('cmrjcvy6l01e3cjeww7m3d57u','24904','Espacios Exterior','Accesorios','Hierro','Max Core','Accesorios','Tornillo FIX 4x30',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,17.16,NULL,NULL,'$',NULL,NULL,NULL,NULL,NULL,'Las Grampas de la línea Bulk de MaxCore son accesorios esenciales fabricados en WPC diseñados para la fijación técnica de tablas de deck. Su uso permite una instalación precisa y segura, manteniendo la separación adecuada entre piezas y asegurando la estabilidad del revestimiento exterior. Al ser parte del sistema MaxCore, son resistentes a la corrosión y están diseñadas para complementar la durabilidad y el acabado estético de los proyectos de deck de madera compuesta.',1,'2026-07-13T15:07:16.558+00:00','2026-07-28T20:04:28.701+00:00',NULL,0);
INSERT INTO decks VALUES('cms533xww0106cj9w8iplj1jq','25463','Espacios Exterior','Deck','WPC','Max Core','Europa','Classic Light Coffee','25',NULL,'140',NULL,'3660',NULL,'0.51',NULL,18.309,35.9,5.002459016,'U$S','["/25463-1.jpg","/25463-2.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Classic Light Coffee de la línea Europa de MaxCore es un revestimiento para exteriores de tono marrón claro y cálido que recrea de manera sofisticada la estética de la madera natural. Con dimensiones de 25 mm de espesor, 14 cm de ancho y un largo de 3.66 m, ofrece un excelente rendimiento de 0.51 m2 por tabla. Fabricado con un compuesto de polímeros de alta calidad y fibras de madera, destaca por ser un producto altamente resistente a la intemperie, la humedad y los rayos UV, 100% libre de mantenimiento al no requerir lijado, barnizado ni sellado.\n\nDebido a su diseño moderno y alta durabilidad, es ideal para jerarquizar espacios al aire libre de tránsito frecuente como terrazas, galerías, balcones, quinchos o bordes de piscinas. Su instalación es rápida y eficiente, adaptándose a estructuras de soporte sobre diversas superficies para garantizar un acabado impecable, nivelado y antideslizante.','\n',char(10)),1,'2026-07-28T20:04:29.168+00:00','2026-07-28T20:04:29.168+00:00',NULL,0);
INSERT INTO decks VALUES('cms533y8j0109cj9wxj8261i7','25464','Espacios Exterior','Deck','WPC','Max Core','Europa','Classic Dark Coffee','25',NULL,'140',NULL,'3660',NULL,'0.51',NULL,18.309,35.9,5.002459016,'U$S','["/25464-1.jpg","/25464-2.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Dark Coffee de la línea Europa de MaxCore es un revestimiento para exteriores de tono oscuro y profundo que aporta calidez y elegancia a cualquier ambiente. Fabricado con un compuesto de polímeros y fibras de madera, es altamente resistente a la intemperie, al sol y a la humedad, destacándose por ser un producto de bajo mantenimiento que no requiere lijado ni barnizado.\n\nDebido a su diseño contemporáneo y presencia visual, se sugerirá su uso para jerarquizar espacios exteriores como terrazas, galerías, balcones o bordes de piscinas. Puede instalarse sobre diversas superficies utilizando un sistema de fijación oculta, lo que garantiza una estética limpia y estable para proyectos residenciales de alta calidad.','\n',char(10)),1,'2026-07-28T20:04:29.588+00:00','2026-07-28T20:04:29.588+00:00',NULL,0);
INSERT INTO decks VALUES('cms533yle010ccj9wn2nyttwv','25461','Espacios Exterior','Deck','WPC','Max Core','Europa','Classic Teak','25',NULL,'140',NULL,'3660',NULL,'0.51',NULL,18.309,35.9,5.002459016,'U$S','["/25461-1.jpg","/25461-2.jpg"]',NULL,NULL,NULL,NULL,'El Deck WPC Teak de la línea Europa de MaxCore es un revestimiento para exteriores de tono cálido que recrea fielmente la estética de la madera clásica. Fabricado con un compuesto de polímeros y fibras de madera, es altamente resistente a la intemperie, al sol y a la humedad, destacándose por ser un producto 100% libre de mantenimiento que no requiere lijado ni barnizado. Debido a su diseño sofisticado que aporta calidez, se sugiere su uso para jerarquizar espacios exteriores como terrazas, galerías, balcones, quinchos o bordes de piscinas, pudiendo instalarse sobre diversas superficies.',1,'2026-07-28T20:04:30.050+00:00','2026-07-28T20:04:30.050+00:00',NULL,0);
INSERT INTO decks VALUES('cms533yxd010fcj9whl2evt5u','25462','Espacios Exterior','Deck','WPC','Max Core','Europa','Classic Gray','25',NULL,'140',NULL,'3660',NULL,'0.51',NULL,18.309,35.9,5.002459016,'U$S','["/25462-1.jpg","/25462-2.jpg"]',NULL,NULL,NULL,NULL,replace('El Deck WPC Gray de la línea Europa de MaxCore es un revestimiento para exteriores de tono gris moderno y sofisticado que recrea de manera elegante la estética de la madera natural. Con dimensiones de 25 mm de espesor, 14 cm de ancho y un largo de 3.66 m, ofrece un excelente rendimiento de 0.51 m2 por tabla. Fabricado con un compuesto de polímeros de alta calidad y fibras de madera, destaca por ser un producto altamente resistente a la intemperie, la humedad y los rayos UV, 100% libre de mantenimiento al no requerir lijado, barnizado ni sellado.\n\nDebido a su diseño contemporáneo que combina a la perfección con superficies modernas, es ideal para jerarquizar espacios al aire libre de tránsito frecuente como terrazas, galerías, balcones, quinchos o bordes de piscinas. Su instalación es rápida y eficiente, adaptándose a estructuras de soporte sobre diversas superficies para garantizar un acabado impecable, nivelado y antideslizante.','\n',char(10)),1,'2026-07-28T20:04:30.482+00:00','2026-07-28T20:04:30.482+00:00',NULL,0);
INSERT INTO decks VALUES('cms533za9010icj9wvftlr5jj','25465','Espacios Exterior','Accesorios','WPC','Max Core','Accesorios','Angulos END Europa varios colores','41',NULL,'41',NULL,'3000',NULL,NULL,NULL,NULL,NULL,NULL,'U$S',NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-07-28T20:04:30.945+00:00','2026-07-28T20:04:30.945+00:00',NULL,0);
