INSERT INTO accesorios VALUES('cmrp8px8c0003cj2odf4ds2u6','25450','Accesorios','Adhesivos','Kekol K645 - Para pisos Vinilicos',NULL,'10kg.',NULL,NULL,NULL,'Adhesivo acrílico premium libre de solventes, diseñado para el pegado de pisos vinílicos, losetas y alfombras. Destaca por su gran agarre inicial, su película de alta elasticidad que resiste el tránsito intenso y su compatibilidad con sistemas de losa radiante.',1,'2026-07-17T17:57:13.980+00:00','2026-07-28T20:05:05.292+00:00',NULL,0);
